68. public class MaxmindDataAdapter extends LookupDataAdapter {
69. 
70.     private static final Logger LOG = getLogger(MaxmindDataAdapter.class);
71. 
72.     public static final String NAME = "maxmind_geoip";
73.     private final Config config;
74.     private final boolean disableIpInfoDbTypeCheck;
75.     private final AtomicReference<IPLocationDatabaseAdapter> databaseAdapter = new AtomicReference<>();
76.     private FileInfo fileInfo = FileInfo.empty();
77. 
78.     @Inject
79.     protected MaxmindDataAdapter(@Assisted("id") String id,
80.                                  @Assisted("name") String name,
81.                                  @Assisted LookupDataAdapterConfiguration config,
82.                                  @Named(DISABLE_IPINFO_DB_TYPE_CHECK) boolean disableIpInfoDbTypeCheck,
83.                                  MetricRegistry metricRegistry) {
84.         super(id, name, config, metricRegistry);
85.         this.config = (Config) config;
86.         this.disableIpInfoDbTypeCheck = disableIpInfoDbTypeCheck;
87.     }
88. 
89.     @Override
90.     protected void doStart() throws Exception {
91.         Path path = Paths.get(config.path());
92.         fileInfo = FileInfo.forPath(path);
93. 
94.         if (!Files.isReadable(path)) {
95.             LOG.warn("Cannot read database file {}", config.path());
96.             setError(new IllegalStateException("Cannot read database file " + config.path()));
97.         } else {
98.             try {
99.                 this.databaseAdapter.set(loadDatabaseAdapter(path.toFile()));
100.             } catch (Exception e) {
101.                 LOG.warn("Unable to read data base file {}", config.path());
102.                 setError(e);
103.             }
104.         }
105.     }
106. 
107.     @Override
108.     protected void doStop() throws Exception {
109.         final IPLocationDatabaseAdapter databaseReader = this.databaseAdapter.get();
110.         if (databaseReader != null) {
111.             databaseReader.close();
112.         }
113.     }
114. 
115.     @Override
116.     public Duration refreshInterval() {
117.         if (config.checkIntervalUnit() == null || config.checkInterval() == 0) {
118.             return Duration.ZERO;
119.         }
120.         //noinspection ConstantConditions
121.         return Duration.millis(config.checkIntervalUnit().toMillis(config.checkInterval()));
122.     }
123. 
124.     @Override
125.     protected void doRefresh(LookupCachePurge cachePurge) throws Exception {
126.         try {
127.             final FileInfo.Change databaseFileCheck = fileInfo.checkForChange();
128.             if (!databaseFileCheck.isChanged() && !getError().isPresent()) {
129.                 return;
130.             }
131. 
132.             // file has different attributes, let's reload it
133.             LOG.debug("MaxMind database file has changed, reloading it from {}", config.path());
134.             final IPLocationDatabaseAdapter oldAdapter = this.databaseAdapter.get();
135.             try {
136.                 this.databaseAdapter.set(loadDatabaseAdapter(Paths.get(config.path()).toFile()));
137.                 cachePurge.purgeAll();
138.                 if (oldAdapter != null) {
139.                     oldAdapter.close();
140.                 }
141.                 fileInfo = databaseFileCheck.fileInfo();
142.                 clearError();
143.             } catch (IOException e) {
144.                 LOG.warn("Unable to load changed database file, leaving old one intact. Error message: {}", e.getMessage());
145.                 setError(e);
146.             }
147.         } catch (IllegalArgumentException iae) {
148.             LOG.error("Unable to refresh MaxMind database file: {}", iae.getMessage());
149.             setError(iae);
150.         }
151.     }
152. 
153.     private IPLocationDatabaseAdapter loadDatabaseAdapter(File file) throws IOException {
154.         switch (config.dbType()) {
155.             case MAXMIND_ASN:
156.             case MAXMIND_CITY:
157.             case MAXMIND_COUNTRY:
158.                 return new MaxMindIPLocationDatabaseAdapter(file);
159.             case IPINFO_ASN:
160.             case IPINFO_STANDARD_LOCATION:
161.                 return new IPinfoIPLocationDatabaseAdapter(file, disableIpInfoDbTypeCheck);
162.             default:
163.                 throw new IllegalStateException("Unexpected value: " + config.dbType());
164.         }
165.     }
