167.     @Override
168.     protected LookupResult doGet(Object key) {
169.         final InetAddress addr;
170.         if (key instanceof InetAddress) {
171.             addr = (InetAddress) key;
172.         } else {
173.             // try to convert it somehow
174.             try {
175.                 addr = InetAddresses.forString(key.toString());
176.             } catch (IllegalArgumentException e) {
177.                 LOG.warn("Unable to parse IP address, returning empty result.");
178.                 return LookupResult.empty();
179.             }
180.         }
181.         final IPLocationDatabaseAdapter reader = this.databaseAdapter.get();
182.         switch (config.dbType()) {
183.             case MAXMIND_CITY:
184.                 try {
185.                     final CityResponse city = reader.maxMindCity(addr);
186.                     if (city == null) {
187.                         LOG.debug("No city data for IP address {}, returning empty result.", addr);
188.                         return LookupResult.empty();
189.                     }
190. 
191.                     final Location location = city.getLocation();
192.                     final Map<Object, Object> map = new HashMap<>();
193.                     map.put("city", city.getCity());
194.                     map.put("continent", city.getContinent());
195.                     map.put("country", city.getCountry());
196.                     map.put("location", location);
197.                     map.put("postal", city.getPostal());
198.                     map.put("registered_country", city.getRegisteredCountry());
199.                     map.put("represented_country", city.getRepresentedCountry());
200.                     map.put("subdivisions", city.getSubdivisions());
